import { Button, Text } from "@chakra-ui/react";
import { ExternalLink, Icon } from "../../../Icon";
import { formatDateTime } from "../../../utils";
import { InfoField } from "./InfoField";

interface CommonEventInfoProps {
  readonly event: {
    timestamp: string;
    id: string;
    conversationEventType: string;
    metadata?: {
      langfuse_trace_url?: string;
      langfuse_trace_id?: string;
    };
  };
}

export const CommonEventInfo = ({ event }: CommonEventInfoProps) => {
  const formatted = formatDateTime(new Date(event.timestamp));
  const traceUrl = event.metadata?.langfuse_trace_url;
  const traceId = event.metadata?.langfuse_trace_id;

  return (
    <>
      {traceUrl ? (
        <InfoField label="Trace" data-testid="event-trace-link">
          <Button
            asChild
            variant="ghost"
            size="sm"
            px="0"
            justifyContent="flex-start"
            aria-label={traceId ? `Open trace ${traceId}` : "Open trace"}
          >
            <a href={traceUrl} target="_blank" rel="noopener noreferrer">
              <Icon icon={ExternalLink} />
              Open in Langfuse
            </a>
          </Button>
        </InfoField>
      ) : null}

      <InfoField label="Occurred at" data-testid="event-occurred-at">
        <Text textStyle="sm">{formatted}</Text>
      </InfoField>

      <InfoField label="ID">
        <Text textStyle="sm" wordBreak="break-all">
          {event.id}
        </Text>
      </InfoField>

      <InfoField label="Type" data-testid="event-type">
        <Text textStyle="sm">{event.conversationEventType}</Text>
      </InfoField>
    </>
  );
};
